import pandas as pd
import numpy as np


TARGET_COLUMN = 'target'


class DecisionTree:
    """Simple regression tree."""
    def __init__(self, max_depth=4, min_leaf=10, n_thresholds=20, col_frac=0.7, rng=None):
        self.max_depth = max_depth
        self.min_leaf = min_leaf
        self.n_thresholds = n_thresholds
        self.col_frac = col_frac
        self.rng = rng
        self.tree = None

    def _best_split(self, X, y, rng=None):
        n, p = X.shape
        best_loss = np.inf
        best = None
        # Feature subsampling for diversity and speed
        if rng is not None and self.col_frac < 1.0:
            n_cols = max(1, int(p * self.col_frac))
            cols = rng.choice(p, n_cols, replace=False)
        else:
            cols = range(p)
        for j in cols:
            col = X[:, j]
            thresholds = np.percentile(col, np.linspace(5, 95, self.n_thresholds))
            for t in thresholds:
                left = col <= t
                right = ~left
                nl, nr = left.sum(), right.sum()
                if nl < self.min_leaf or nr < self.min_leaf:
                    continue
                loss = np.var(y[left]) * nl + np.var(y[right]) * nr
                if loss < best_loss:
                    best_loss = loss
                    best = (j, t)
        return best

    def _build(self, X, y, depth):
        if depth >= self.max_depth or len(y) < 2 * self.min_leaf:
            return ('leaf', y.mean())
        split = self._best_split(X, y, self.rng)
        if split is None:
            return ('leaf', y.mean())
        j, t = split
        left = X[:, j] <= t
        right = ~left
        return ('node', j, t, self._build(X[left], y[left], depth + 1),
                self._build(X[right], y[right], depth + 1))

    def fit(self, X, y):
        self.tree = self._build(X, y, 0)

    def _predict_one(self, tree, x):
        if tree[0] == 'leaf':
            return tree[1]
        _, j, t, left, right = tree
        if x[j] <= t:
            return self._predict_one(left, x)
        return self._predict_one(right, x)

    def predict(self, X):
        return np.array([self._predict_one(self.tree, x) for x in X])


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    """Gradient boosted trees with entity aggregation."""
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    features = [c for c in train.columns if c.startswith('x')]

    # Aggregate by entity
    train_agg = train.groupby('entity_id')[features + [TARGET_COLUMN]].mean().reset_index()

    X_train = train_agg[features].values
    y_train = train_agg[TARGET_COLUMN].values
    X_test = test[features].values

    # Gradient boosting
    lr = 0.08
    n_rounds = 400
    rng = np.random.RandomState(42)
    base_pred = y_train.mean()
    train_preds = np.full(len(y_train), base_pred)
    test_preds = np.full(len(X_test), base_pred)

    for i in range(n_rounds):
        residuals = y_train - train_preds
        tree = DecisionTree(max_depth=5, min_leaf=8, n_thresholds=30, col_frac=0.7, rng=rng)
        tree.fit(X_train, residuals)
        train_preds += lr * tree.predict(X_train)
        test_preds += lr * tree.predict(X_test)

    predictions = pd.DataFrame({"prediction": test_preds})
    predictions.to_csv(output_csv, index=False)

